#!/usr/bin/env node
// Writes design.css, components.html and the Tokens block of spec.md for every design with status "finished".
// These are plain files Claude can read where the renderer cannot run (claude.ai chat). Generated from tokens.json: do not edit by hand.
// Usage: node build-design-files.mjs [--check]   (--check exits 1 if any file is out of date)
import { readdirSync, readFileSync, writeFileSync, existsSync } from 'node:fs';
import { join } from 'node:path';
import { SKILL_DIR, SYSTEMS_DIR, loadTokens, readJson, esc } from './lib/util.mjs';
import { buildCss, fontStacks, familiesUsed } from './lib/css.mjs';
import { buildHtml } from './lib/html.mjs';
import { loadManifest } from './lib/fonts.mjs';

const START = '<!-- TOKENS:START (generated by scripts/build-design-files.mjs; do not edit by hand) -->', END = '<!-- TOKENS:END -->';
const HEADER = 'Generated from tokens.json by scripts/build-design-files.mjs. Do not edit by hand.';

const lum = (hex) => {
  const [r, g, b] = [1, 3, 5].map((i) => parseInt(hex.slice(i, i + 2), 16) / 255).map((v) => (v <= 0.03928 ? v / 12.92 : ((v + 0.055) / 1.055) ** 2.4));
  return 0.2126 * r + 0.7152 * g + 0.0722 * b;
};
const contrast = (a, b) => { const [x, y] = [lum(a), lum(b)].sort((p, q) => q - p); return (x + 0.05) / (y + 0.05); };

/** Same background rule as buildCss: the sidebar colour is painted behind the sidebar column. */
function pageBackground(t, rtl) {
  const c = t.colors, L = t.layout, s = t.sizes, sp = t.spacing;
  if (L.kind !== 'sidebar' || c.sidebarBg.toLowerCase() === c.bg.toLowerCase() || L.headerFull) return c.bg; // same rule as buildCss: no page-height tint
  const edge = `${s.marginSide}mm + ${L.sidebarWidth} + ${sp.gutter / 2}mm`;
  return `linear-gradient(to ${rtl ? 'left' : 'right'}, ${c.sidebarBg} 0, ${c.sidebarBg} calc(${edge}), ${c.bg} calc(${edge}))`;
}

function fontFaces(t) {
  const man = loadManifest(join(SKILL_DIR, 'fonts'));
  let css = '';
  for (const fam of familiesUsed(t)) for (const f of man[fam] ?? []) {
    css += `@font-face{font-family:"${fam}";font-weight:${f.weight};font-style:normal;src:url("../../fonts/${f.file}") format("woff2");${f.range ? `unicode-range:${f.range};` : ''}}\n`;
  }
  return css;
}

function designCss(t) {
  const c = t.colors, s = t.sizes;
  const sidebarVars = t.layout.kind === 'sidebar' ? `--sidebar-bg:${c.sidebarBg};--sidebar-text:${c.sidebarText};--sidebar-muted:${c.sidebarMuted};--sidebar-accent:${c.sidebarAccent};` : '';
  const arabic = fontStacks(t, 'arabic', 'ar').body;
  return `/* ${t.id} ${t.name}. ${HEADER}
   Fonts are bundled in ../../fonts (OFL). Load this file in a page, or copy the rules into a <style> block. */
${fontFaces(t)}${buildCss(t, { rtl: false, script: 'latin', lang: 'en' }).trim()}
:root{${sidebarVars}}
/* RTL and Arabic-script variant: RTL is a flag of the same design, not a separate design. */
html[dir="rtl"]{background:${pageBackground(t, true)}}
html[data-script="arabic"] body{font-family:${arabic};line-height:${s.arabicLineHeight ?? s.lineHeight + 0.15}}
html[data-script="arabic"] h1{letter-spacing:0}
`;
}

const body = (html) => {
  const m = html.match(/<body>([\s\S]*)<\/body>/);
  if (!m) throw new Error('buildHtml output has no <body>');
  return m[1];
};

const COMPONENTS = [
  ['.head h1', 'Name'], ['.headline', 'Headline'], ['.contact', 'Contact list (in the body, never only in a header or footer)'],
  ['.sec > h2', 'Section heading'], ['.entry', 'Entry (title, dates, employer, bullets)'], ['.bul', 'Bullet list'],
  ['.chips', 'Skills as plain text, no bars or percentages'], ['.lang-list', 'Languages as words'],
];

/** Same rule as buildCss: sidebar, band header or non-white page colour bleed to the page edge, and .layout carries the margins. */
const bleeds = (t) => t.layout.kind === 'sidebar' || t.layout.header === 'band' || t.colors.bg.toLowerCase() !== '#ffffff';

function componentsHtml(t) {
  const en = readJson(join(SKILL_DIR, 'test-data', 'short.json'));
  const ar = readJson(join(SKILL_DIR, 'test-data', 'ar.json'));
  const parts = [['en', 'ltr', 'English (LTR)', en], ['ar', 'rtl', 'Arabic (RTL variant of the same design)', ar]];
  const sheets = parts.map(([lang, dir, label, cv]) => {
    const { html } = buildHtml(cv, t, { rtlFlag: dir === 'rtl' ? 'on' : 'off' });
    return `<section class="demo"><h2 class="demo-title">${esc(label)}</h2><div class="sheet" lang="${lang}" dir="${dir}" data-script="${lang === 'ar' ? 'arabic' : 'latin'}" style="background:${pageBackground(t, dir === 'rtl')}">${body(html)}</div></section>`;
  }).join('\n');
  const vars = Object.entries(t.colors).map(([k, v]) => `<li><span class="sw" style="background:${v}"></span><code>${esc(k)}</code> ${esc(v)}</li>`).join('');
  const list = (t.layout.kind === 'sidebar' ? [...COMPONENTS, ['.side', 'Sidebar column (' + t.layout.sidebarSections.join(', ') + ')']] : COMPONENTS)
    .map(([sel, what]) => `<li><code>${esc(sel)}</code> ${esc(what)}</li>`).join('');
  return `<!doctype html>
<html lang="en"><head><meta charset="utf-8"><title>${esc(t.id)} ${esc(t.name)}: components</title><meta name="viewport" content="width=device-width,initial-scale=1">
<!-- ${HEADER} -->
<link rel="stylesheet" href="design.css">
<style>
html{background:#f1f3f5}
body{font-family:Inter,"IBM Plex Sans Arabic",sans-serif}
.doc{max-width:230mm;margin:0 auto;padding:16px}
.doc h1.page-title{font-size:20px;margin:0 0 4px}
.legend,.swatches{display:flex;flex-wrap:wrap;gap:4px 18px;font-size:13px;margin:8px 0 16px}
.sw{display:inline-block;width:14px;height:14px;border:1px solid #888;vertical-align:-2px;margin-inline-end:4px}
.demo-title{font-size:14px;margin:24px 0 8px}
.sheet{width:210mm;max-width:100%;margin:0 auto;padding:${bleeds(t) ? '0' : '14mm 13mm'};box-shadow:0 1px 6px rgba(0,0,0,.25)}
</style></head>
<body><div class="doc">
<h1 class="page-title">${esc(t.id)} ${esc(t.name)}: components</h1>
<p>ATS tier ${esc(t.atsTier)}${t.twin ? `; plain twin ${esc(t.twin)}` : ''}. Rules: <a href="spec.md">spec.md</a>. Styling: <a href="design.css">design.css</a>. Synthetic sample content only.</p>
<ul class="swatches">${vars}</ul>
<ul class="legend">${list}</ul>
${sheets}
</div></body></html>
`;
}

function tokensBlock(t) {
  const c = t.colors, s = t.sizes, sp = t.spacing, L = t.layout;
  const pairs = [['text', 'bg'], ['muted', 'bg'], ['accent', 'bg'], ['rule', 'bg'], ['bandText', 'bandBg'], ['ribbonText', 'ribbonBg'], ['sidebarText', 'sidebarBg'], ['sidebarMuted', 'sidebarBg'], ['sidebarAccent', 'sidebarBg']].filter(([a, b]) => c[a] && c[b]);
  const rows = Object.entries(c).map(([k, v]) => {
    const p = pairs.find(([a]) => a === k);
    return `| \`${k}\` | \`${v}\` | ${p ? `${contrast(v, c[p[1]]).toFixed(2)}:1 on \`${p[1]}\`` : 'background'} |`;
  });
  const fonts = Object.entries(t.fonts).map(([role, f]) => `| ${role} | ${f.latin} | ${f.arabic} | ${f.weight} |`);
  return `${START}
## Tokens (colours, type, spacing)
Source: \`tokens.json\`. Styling: \`design.css\`. Components: \`components.html\`.

| Colour | Hex | Contrast |
|---|---|---|
${rows.join('\n')}

| Font role | Latin | Arabic script | Weight |
|---|---|---|---|
${fonts.join('\n')}

- Page ${s.page}; base ${s.base}pt, name ${s.name}pt, headline ${s.headline}pt, heading ${s.heading}pt, small ${s.small}pt; line height ${s.lineHeight} (Arabic ${s.arabicLineHeight ?? 'n/a'}).
- Margins (mm) top ${s.marginTop}, sides ${s.marginSide}, bottom ${s.marginBottom}. Spacing (pt): section ${sp.section}, item ${sp.item}, bullet ${sp.bullet}, gutter ${sp.gutter}mm.
- Layout: ${L.kind}${L.kind === 'sidebar' ? ` (sidebar ${L.sidebarWidth}: ${L.sidebarSections.join(', ')}${L.headerFull ? '; header spans both columns' : ''})` : ''}${L.kind === 'labelled' ? ` (label column ${L.labelWidth})` : ''}; header ${L.header}${L.headerAlign === 'center' ? ' centred' : ''}; headings ${L.headingStyle}, case ${L.headingCase}; bullets ${L.bulletStyle}; dates ${L.dateAlign}${['entryStyle', 'skillsStyle', 'projectsStyle', 'highlightsStyle'].filter((k) => L[k]).map((k) => `; ${k.replace('Style', '')} ${L[k]}`).join('')}; max pages ${t.limits?.maxPages ?? 2}.
${END}`;
}

function withBlock(spec, block) {
  if (spec.includes(START)) return spec.replace(new RegExp(`${START.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}[\\s\\S]*?${END}`), () => block);
  const at = spec.indexOf('## Check results');
  if (at < 0) throw new Error('spec.md has no "## Check results" heading to place the Tokens block before');
  return spec.slice(0, at) + block + '\n\n' + spec.slice(at);
}

export function buildAll({ check = false } = {}) {
  const stale = [];
  const write = (path, text) => {
    const same = existsSync(path) && readFileSync(path, 'utf8') === text;
    if (check) { if (!same) stale.push(path); } else if (!same) writeFileSync(path, text);
  };
  for (const d of readdirSync(SYSTEMS_DIR, { withFileTypes: true }).filter((e) => e.isDirectory())) {
    const { tokens: t, errors } = loadTokens(d.name.split('-')[0]);
    if (errors.length) throw new Error(`${d.name}: tokens.json invalid:\n  ${errors.join('\n  ')}`);
    if (t.status !== 'finished') continue;
    const dir = join(SYSTEMS_DIR, d.name);
    write(join(dir, 'design.css'), designCss(t));
    write(join(dir, 'components.html'), componentsHtml(t));
    write(join(dir, 'spec.md'), withBlock(readFileSync(join(dir, 'spec.md'), 'utf8'), tokensBlock(t)));
  }
  return stale;
}

if (import.meta.url === `file://${process.argv[1]}`) {
  const check = process.argv.includes('--check');
  const stale = buildAll({ check });
  if (stale.length) { console.error('Out of date (run: node scripts/build-design-files.mjs):\n  ' + stale.join('\n  ')); process.exit(1); }
  console.log(check ? 'Design files are up to date.' : 'Design files written.');
}
